pub export fn isFunctionOldParam16(func: u16) callconv(.c) bool_t {
    const f: i16 = @bitCast(func);
    return @intFromBool(f == ITM_BESTF_OLD or
        f == ITM_RNG_OLD or
        f == ITM_YY_DFLT_OLD or
        f == ITM_DENMAX2_OLD);
}

