// max(itemNr, -itemNr) == abs(itemNr) for the switch
fn itemERRTIVal(itemNr: i16) u8 {
    const key = cabs16(itemNr);
    if (comptime dmcp_build) {
        switch (key) {
            ITM_WRXPALL => return _TO_ITM_ERR,
            else => return _TO_ITM_NONE,
        }
    } else {
        switch (key) {
            ITM_SAVEAUT, ITM_SETDAT, ITM_SETTIM, ITM_SYSTEM2, ITM_ACTUSB => return _TO_ITM_ERR,
            ITM_DISK, ITM_BUZZ, ITM_PLAY, ITM_VOL, ITM_VOLMINUS, ITM_VOLPLUS, ITM_VOLQ, ITM_BATT => return _TO_ITM_TI,
            else => return _TO_ITM_NONE,
        }
    }
}

pub export fn itemNotAvail(itemNr: i16) callconv(.c) bool_t {
    // DMCP_BUILD || PC_BUILD always true (frontier targets)
    if (comptime ir_printing) {
        if (itemNr == ITM_PRINTERLCD and printerState.printer_model != PRINTER_MARTEL) {
            return 1;
        }
    }
    if (itemERRTIVal(itemNr) != _TO_ITM_NONE) {
        return 1;
    }
    return 0;
}

pub export fn indirectionType(func: u16) callconv(.c) u16 {
    switch (indexOfItems[func].param) {
        @as(u16, @bitCast(TM_FLAGR)), @as(u16, @bitCast(TM_FLAGW)) => {
            return INDPM_FLAG;
        },
        @as(u16, @bitCast(TM_STORCL)), @as(u16, @bitCast(TM_REGISTER)), @as(u16, @bitCast(TM_CMP)), @as(u16, @bitCast(TM_M_DIM)) => {
            return INDPM_REGISTER;
        },
        @as(u16, @bitCast(TM_LBLONLY)), @as(u16, @bitCast(TM_LABEL)) => {
            return INDPM_LABEL;
        },
        @as(u16, @bitCast(TM_MENU)) => {
            return INDPM_MENU;
        },
        @as(u16, @bitCast(TM_SOLVE)) => {
            const f: i16 = @bitCast(func);
            if (f == ITM_SOLVE) {
                return if (programRunStop == PGM_RUNNING) INDPM_REGISTER else INDPM_LABEL;
            } else if (f == ITM_PGMSLV) {
                return INDPM_LABEL;
            } else {
                return INDPM_PARAM;
            }
        },
        else => {
            return INDPM_PARAM;
        },
    }
}

const empty_str: [*c]u8 = @constCast("");

pub export fn lastFuncCatalogName() callconv(.c) [*c]u8 {
    if (lastFunc == ITM_VERS or lastFunc == NOPARAM) {
        return empty_str;
    }
    if (lastFunc == ITM_CNST) {
        if (lastParam <= LAST_CONSTANT - FIRST_CONSTANT - 1) {
            const addOffset: i16 = if (lastParam > @as(i16, @bitCast(indexOfItems[@intCast(ITM_CNST - 1)].param))) 1 else 0;
            _ = strcpy(lastTemp, &indexOfItems[@intCast(lastParam + 128 + addOffset)].itemCatalogName);
        } else {
            lastTemp[0] = 0;
        }
    } else {
        _ = strcpy(lastTemp, &indexOfItems[@intCast(lastFunc)].itemCatalogName);
    }
    return lastTemp;
}

pub export fn lastFuncSoftmenuName() callconv(.c) [*c]u8 {
    if (lastFunc == ITM_VERS or lastFunc == NOPARAM) {
        return empty_str;
    }
    if (lastFunc == ITM_CNST) {
        if (lastParam <= LAST_CONSTANT - FIRST_CONSTANT - 1) {
            const addOffset: i16 = if (lastParam > @as(i16, @bitCast(indexOfItems[@intCast(ITM_CNST - 1)].param))) 1 else 0;
            _ = strcpy(lastTemp, &indexOfItems[@intCast(lastParam + 128 + addOffset)].itemSoftmenuName);
        } else {
            lastTemp[0] = 0;
        }
    } else {
        _ = strcpy(lastTemp, &indexOfItems[@intCast(lastFunc)].itemSoftmenuName);
    }
    return lastTemp;
}

pub export fn lastSTORCL() callconv(.c) i16 {
    return lastParam;
}

pub export fn lastFuncNo() callconv(.c) i16 {
    return lastFunc;
}

pub export fn getItemCatalogName(itemNr: i16) callconv(.c) [*c]u8 {
    var itemName: [*c]u8 = undefined;
    if (cabs16(itemNr) <= LAST_ITEM) { // Predefined item
        itemName = @constCast(&indexOfItems[@intCast(cabs16(itemNr))].itemCatalogName);
    } else if (itemNr >= ASSIGN_LABELS) { // User program
        var lblPtr: [*c]u8 = labelList[@intCast(itemNr - ASSIGN_LABELS)].labelPointer;
        const count: u32 = lblPtr[0];
        lblPtr += 1;
        var tbPtr: [*c]u8 = tmpStringLabelOrVariableName;
        var i: u32 = 0;
        while (i < count) : (i += 1) {
            tbPtr[0] = lblPtr[0];
            tbPtr += 1;
            lblPtr += 1;
        }
        tbPtr[0] = 0;
        itemName = tmpStringLabelOrVariableName;
    } else if (itemNr >= ASSIGN_RESERVED_VARIABLES) { // Reserved variable
        itemName = @ptrCast(@constCast(&allReservedVariables[@intCast(itemNr - ASSIGN_RESERVED_VARIABLES)].reservedVariableName[1]));
    } else if (itemNr >= ASSIGN_NAMED_VARIABLES) { // User variable
        itemName = @ptrCast(&allNamedVariables[@intCast(itemNr - ASSIGN_NAMED_VARIABLES)].variableName[1]);
    } else if (itemNr <= ASSIGN_USER_MENU) { // User menu
        itemName = @ptrCast(&userMenus[@intCast(ASSIGN_USER_MENU - itemNr)].menuName);
    } else { // unknown item, return empty string
        tmpStringLabelOrVariableName[0] = 0;
        itemName = tmpStringLabelOrVariableName;
    }
    return itemName;
}

pub export fn getItemFunc(itemNr: i16) callconv(.c) ItemFn {
    var func: ItemFn = undefined;
    if (cabs16(itemNr) <= LAST_ITEM) { // Predefined item
        func = indexOfItems[@intCast(itemNr)].func;
    } else { // Any other user or reserved item
        func = ext_addItemToBuffer;
    }
    return func;
}
const ext_addItemToBuffer = @extern(ItemFn, .{ .name = "addItemToBuffer" });

pub export fn reallyRunFunction(func: i16, param: u16) callconv(.c) void {
    // IR_PRINTING tracing block
    if (comptime ir_printing) {
        if (frontier_softmenus.isFunctionItemAMenu(func) == 0 and indexOfItems[@intCast(func)].func != ext_addItemToBuffer) {
            if (programRunStop != PGM_RUNNING and programRunStop != PGM_SINGLE_STEP) {
                if (calcMode != CM_MIM or (func != ITM_LEFT_ARROW and func != ITM_UP_ARROW and
                    func != ITM_RIGHT_ARROW and func != ITM_DOWN_ARROW and
                    func != ITM_op_j and func != ITM_op_j_pol))
                {
                    if (!((func == ITM_toREAL) and (lastFunc == ITM_dotD))) {
                        frontier_print.printTrace(func, param);
                    }
                }
            }
        }
    }

    const funcIsProgramStopControl: bool = (func == ITM_END or func == ITM_RTN or func == ITM_STOP or func == ITM_RTNP1);
    if (!funcIsProgramStopControl) {
        lastFunc = func;
        lastParam = @bitCast(param);
    }

    if (func != ITM_SOLVE_VAR and (calcMode == CM_NORMAL or calcMode == CM_NIM) and
        (frontier_softmenus.currentMenu() == -MNU_MVAR) and
        (currentSolverStatus == 258 or currentSolverStatus == 259))
    {
        currentSolverStatus &= ~SOLVER_STATUS_READY_TO_EXECUTE;
    }
    if (indexOfItems[@intCast(func)].func != ext_fnTvmVar and (calcMode == CM_NORMAL or calcMode == CM_NIM) and
        frontier_softmenus.currentMenu() == -MNU_TVM and
        (currentSolverStatus & SOLVER_STATUS_TVM_APPLICATION) != 0)
    {
        currentSolverStatus &= ~SOLVER_STATUS_READY_TO_EXECUTE;
    }

    if (func != ITM_CLX) {
        resetKeytimers();
    }
    if (func != ITM_DRG) {
        DRG_Cycling = 0;
    }

    if ((indexOfItems[@intCast(func)].status & US_STATUS) == US_ENABLED or (indexOfItems[@intCast(func)].status & US_STATUS) == US_ENABL_XEQ) {
        if ((programRunStop != PGM_RUNNING or getSystemFlag(@intCast(FLAG_IGN1ER)) != 0) and calcMode != CM_GRAPH and calcMode != CM_NO_UNDO and getSystemFlag(@intCast(FLAG_SOLVING)) == 0 and getSystemFlag(@intCast(FLAG_INTING)) == 0) {
            saveForUndo();
        }

        if (lastErrorCode == ERROR_RAM_FULL) {
            if ((indexOfItems[@intCast(func)].status & US_STATUS) == US_ENABLED or calcMode == CM_CONFIRMATION) {
                frontier_error.displayCalcErrorMessage(@intCast(ERROR_RAM_FULL), ERR_REGISTER_LINE, NIM_REGISTER_LINE);
                return;
            } else {
                lastErrorCode = @intCast(ERROR_NONE);
                temporaryInformation = TI_UNDO_DISABLED;
            }
        }
    } else if (((indexOfItems[@intCast(func)].status & US_STATUS) == US_CANCEL) and calcMode != CM_NO_UNDO) {
        thereIsSomethingToUndo = 0;
    }

    if (programRunStop != PGM_RUNNING) { // NORMAL MODE
        if (comptime !dmcp_build) {
            var tmp: [200]u8 = undefined;
            abi.fmtCStr(&tmp, "^^^^reallyRunFunction func={d} param={d}\n", .{ @as(c_int, func), @as(c_int, @intCast(param)) });
            jm_show_comment(&tmp);
        }

        if ((indexOfItems[@intCast(func)].status & HG_STATUS) == HG_ENABLED or (((indexOfItems[@intCast(func)].status & HG_STATUS) == HG_ENABLED_MX_ONLY) and isXYRegisterMatrix())) {
            hourGlassIconEnabled = 1;
            screenUpdatingMode &= @truncate(~SCRUPD_MANUAL_STATUSBAR);
            frontier_status_bar.showHideHourGlass();
        }

        if (func == ITM_GTO or func == ITM_XEQ or func == ITM_GTOP) {
            while (currentSubroutineLevelData.*.subroutineLevel > 0) {
                frontier_lbl_gto_xeq.fnReturn(0);
            }
            frontier_lbl_gto_xeq.cleanLocalFlagsAndRegisters();
        }

        screenUpdatingMode = @truncate(SCRUPD_AUTO);
    } else { // PGM_RUNNING MODE
        if (func == ITM_GTO or func == ITM_XEQ or func == ITM_GTOP) {
            screenUpdatingMode &= @truncate(~SCRUPD_MANUAL_STATUSBAR);
            frontier_status_bar.showHideHourGlass();
        }
        if (comptime !dmcp_build) {
            frontier_screen.force_refresh(timed_val);
        }
    }

    if ((programRunStop != PGM_RUNNING and func != ITM_LASTT) or func == ITM_XEQ or timeLastOp0 == 0) {
        frontier_timer.LastOpTimerReStart(@bitCast(func));
    } else if (programRunStop == PGM_RUNNING and func == ITM_LASTT) {
        frontier_timer.LastOpTimerLap(@bitCast(func));
    }

    // mark the previous I and J for STOSEQ/RCLSEQ
    var iir: abi.Real = undefined;
    var jjr: abi.Real = undefined;
    if ((func == ITM_RCLELPLUS or func == ITM_STOELPLUS) and isMatrixIndexed() != 0 and frontier_register_value_conversions.getRegisterAsRealQuiet(REGISTER_I, &iir) and frontier_register_value_conversions.getRegisterAsRealQuiet(REGISTER_J, &jjr)) {
        lastI = @truncate(frontier_real_type.realToUint32C47(&iir, null));
        lastJ = @truncate(frontier_real_type.realToUint32C47(&jjr, null));
    } else {
        lastI = 0xFFFF;
        lastJ = 0xFFFF;
    }

    frontier_status_bar.refreshStatusBar();

    // **RunFunction
    if (itemNotAvail(func) == 0) {
        indexOfItems[@intCast(func)].func.?(param);

        if (comptime ir_printing) {
            ext_printTraceTI();
            if (getSystemFlag(@intCast(FLAG_TRACE)) != 0 and (indexOfItems[@intCast(func)].status & RESULT_IN_X) != 0) {
                if (func != ITM_dotD) {
                    ext_printTraceX(LINE_FULL);
                }
            }
            printerState.trace_done = false;
        }
    } else {
        if (itemERRTIVal(func) == _TO_ITM_TI) {
            temporaryInformation = TI_NOT_AVAILABLE;
        } else if (itemERRTIVal(func) == _TO_ITM_ERR) {
            frontier_error.displayCalcErrorMessage(@intCast(notAvail), ERR_REGISTER_LINE, REGISTER_X);
        }
        screenUpdatingMode = @truncate(SCRUPD_AUTO);
    }

    switch (func) {
        ITM_LASTERR, ITM_GTO, ITM_XEQ, ITM_BACK, ITM_CASE, ITM_SKIP => {},
        else => {
            previousErrorCode = lastErrorCode;
        },
    }

    if (programRunStop != PGM_RUNNING) {
        frontier_timer.LastOpTimerLap(@bitCast(func));
    }

    if (funcIsProgramStopControl) {
        screenUpdatingMode &= @truncate(~SCRUPD_MANUAL_STATUSBAR);
        if (currentSubroutineLevelData.*.subroutineLevel == 0) {
            frontier_status_bar.forceSBupdate();
            screenUpdatingMode = @truncate(SCRUPD_AUTO);
        }
    }

    switch (func) {
        ITM_DRAW, ITM_DRAW_LU, VAR_LX, VAR_UX, ITM_PLOT_STAT, ITM_PLINE, ITM_DIFF, ITM_RMS, ITM_PCROS, ITM_PPLUS, ITM_NVECT, ITM_SNAP, ITM_NULL, ITM_SCALE, ITM_INTG, ITM_SHADE, ITM_PBOX, ITM_PCURVE, ITM_VECT, ITM_SHOWX, ITM_SHOWY, ITM_MZOOMY, ITM_PZOOMY, ITM_LISTXY, ITM_PLOTRST, ITM_PLOT_ASSESS, ITM_PLOT_NXT, ITM_PLOT_REV, ITM_PLOT_SCATR, ITM_PLOT_CENTRL, ITM_SMI, ITM_HPLOT, ITM_HNORM, ITM_PLOTZOOM => {
            reDraw = 1;
        },
        else => {},
    }

    if (temporaryInformation == TI_LAST_CONST_CATNAME and (currentSolverStatus & 0x000F) != 0) {
        temporaryInformation = TI_NO_INFO;
    } else if (((FIRST_CONSTANT <= func and func <= LAST_CONSTANT) or func == ITM_CNST) and calcMode == CM_NORMAL) {
        temporaryInformation = TI_LAST_CONST_CATNAME;
    } else if (calcMode == CM_NORMAL and getSystemFlag(@intCast(FLAG_INTING)) == 0 and getSystemFlag(@intCast(FLAG_SOLVING)) == 0) {
        const pi: i16 = @bitCast(param);
        const inRegisterRange: bool = (pi <= LAST_LETTERED_REGISTER or
            (FIRST_STAT_REGISTER <= pi and pi <= LAST_STAT_REGISTER) or
            (FIRST_SPARE_REGISTER <= pi and pi <= LAST_SPARE_REGISTER));
        const inReservedRange: bool = (FIRST_NAMED_RESERVED_VARIABLE <= pi and pi <= LAST_RESERVED_VARIABLE);
        const inNameRegisterRange: bool = (FIRST_NAMED_VARIABLE <= pi and pi <= LAST_NAMED_VARIABLE);
        const inLocalRegisters: bool = (pi >= FIRST_LOCAL_REGISTER and pi < FIRST_LOCAL_REGISTER + @as(i16, @intCast(currentSubroutineLevelData.*.numberOfLocalRegisters)));
        const isMatrix: bool = if (func == ITM_RCL or func == ITM_STO)
            (if (inRegisterRange or inReservedRange or inNameRegisterRange or inLocalRegisters)
                (getRegisterDataType(pi) == dtReal34Matrix or getRegisterDataType(pi) == dtComplex34Matrix)
            else
                false)
        else
            false;
        var rr: u16 = undefined;
        var regStats: calcRegister_t = FAILED_INDIRECTION;
        if (inNameRegisterRange) {
            regStats = findNamedVariable("STATS");
        }

        switch (func) {
            VAR_UEST => {
                solverEstimatesUsed = 1;
            },
            VAR_LEST => {
                solverEstimatesUsed = 1;
            },
            VAR_UX, VAR_LX, VAR_UY, VAR_LY => {
                temporaryInformation = TI_STORCL;
            },
            ITM_STO, ITM_RCL => {
                temporaryInformation =
                    if (pi == REGISTER_I and isMatrixIndexed() != 0) TI_I else if (pi == REGISTER_J and isMatrixIndexed() != 0) TI_J else if (inNameRegisterRange) (if (frontier_stats.isStatsMatrixN(&rr, regStats) and pi == regStats) TI_STATISTIC_SUMS else TI_STORCL) else if (isMatrix) TI_STORCL else if (inReservedRange or inRegisterRange or inLocalRegisters) TI_STORCL else TI_NO_INFO;
            },
            ITM_RCLELPLUS, ITM_RCLEL, ITM_STOELPLUS, ITM_STOEL => {
                if (isMatrixIndexed() != 0) temporaryInformation = TI_MIJEQ;
            },
            ITM_INDEX, ITM_IPLUS, ITM_IMINUS, ITM_JPLUS, ITM_JMINUS => {
                if (isMatrixIndexed() != 0) temporaryInformation = TI_MIJ;
            },
            ITM_RCLIJ, ITM_STOIJ => {
                if (isMatrixIndexed() != 0) temporaryInformation = TI_IJ;
            },
            else => {},
        }

        // TI for conversion menus (items.c:555-573)
        if (lastErrorCode == ERROR_NONE and temporaryInformation == TI_NO_INFO) {
            temporaryInformation = TI_NO_INFO;
            if (frontier_conversion_units.isItemConversion(func)) {
                frontier_conversion_units.executionConversionPartner(func, null, errorMessage);
                errorMessage[0] = 0;
                temporaryInformation = TI_CONV_MENU_STR;
                var i: i16 = 0;
                while (!(STD_RIGHT_ARROW0 == errorMessage[@intCast(i)] and (STD_RIGHT_ARROW1 == errorMessage[@intCast(i + 1)] or STD_RIGHT_SHORT_ARROW1 == errorMessage[@intCast(i + 1)]))) {
                    i += 1;
                }
                i += 2; // step past the two bytes of the right-arrow glyph to the first byte of the second unit name
                var j: i16 = 0;
                while (errorMessage[@intCast(i)] != 0) {
                    errorMessage[@intCast(j)] = errorMessage[@intCast(i)];
                    j += 1;
                    i += 1;
                }
                errorMessage[@intCast(j)] = 0;
                frontier_char_string.expandAbbreviations(errorMessage);
            }
        }
    }

    if (lastErrorCode != 0) {
        if (getSystemFlag(@intCast(FLAG_IGN1ER)) != 0) {
            if (thereIsSomethingToUndo != 0 and (indexOfItems[@intCast(func)].status & US_STATUS) != US_UNCHANGED) {
                undo();
            }
            lastErrorCode = @intCast(ERROR_NONE);
        } else {
            if (thereIsSomethingToUndo != 0 and (indexOfItems[@intCast(func)].status & US_STATUS) != US_UNCHANGED and
                !((func == ITM_EIGVAL or func == ITM_EIGVEC) and lastErrorCode == ERROR_SOLVER_ABORT))
            {
                undo();
            }
        }
        clearSystemFlag(@intCast(FLAG_IGN1ER));
    } else {
        if ((indexOfItems[@intCast(func)].status & SLS_STATUS) == SLS_DISABLED) {
            clearSystemFlag(@intCast(FLAG_ASLIFT));
        } else if ((indexOfItems[@intCast(func)].status & SLS_STATUS) == SLS_ENABLED) {
            setSystemFlag(@intCast(FLAG_ASLIFT));
        }
    }

    if (comptime dmcp_build) {
        _ = updateVbatIntegrated(0);
    }

    if (programRunStop != PGM_RUNNING) {
        frontier_screen.updateMatrixHeightCache();
        cachedDynamicMenu = 0;
        if (comptime !dmcp_build) {
            _ = frontier_screen.refreshLcd(null);
        }
    }
    // PC_BUILD gmpMemInBytes check is a host-only diagnostic (no observable
    // calc-state effect); omitted.
}

// Helpers/externs for reallyRunFunction
const RESULT_IN_X: u16 = 32768;
const REGISTER_Y_v: calcRegister_t = 101;
inline fn isXYRegisterMatrix() bool {
    return (getRegisterDataType(REGISTER_X) == dtReal34Matrix) or (getRegisterDataType(REGISTER_X) == dtComplex34Matrix) or (getRegisterDataType(REGISTER_Y_v) == dtReal34Matrix) or (getRegisterDataType(REGISTER_X) == dtComplex34Matrix);
}
// frontier_screen.force_refresh(timed); timed == 0 (PC_BUILD only)
const timed_val: u8 = 0;

// IR_PRINTING trace externs
inline fn ext_printTraceTI() void {
    frontier_print.printTraceTI();
}
inline fn ext_printTraceX(where: i16) void {
    frontier_print.printTraceX(@bitCast(where));
}

// DMCP-only
extern fn updateVbatIntegrated(arg: bool_t) c_int;

// host-only (PC_BUILD)
extern fn jm_show_comment(comment: [*c]u8) void;

pub export fn runFunction(func: i16) callconv(.c) void {
    funcOK = 1;

    if (programRunStop != PGM_RUNNING) {
        if (func == ITM_RCL and dynamicMenuItem > -1) {
            const varCatalogItem: [*c]u8 = frontier_softmenus.dynmenuGetLabel(dynamicMenuItem);
            if (strcmp(varCatalogItem, "RCL") != 0) {
                const v: calcRegister_t = findNamedVariable(varCatalogItem);
                if (v != INVALID_VARIABLE) {
                    if (calcMode == CM_PEM) {
                        frontier_manage.insertUserItemInProgram(func, varCatalogItem);
                    } else {
                        reallyRunFunction(func, @bitCast(v));
                    }
                } else {
                    frontier_error.displayCalcErrorMessage(@intCast(ERROR_UNDEF_SOURCE_VAR), ERR_REGISTER_LINE, REGISTER_X);
                }
                return;
            }
        }
        if (func == ITM_XEQ and dynamicMenuItem > -1) {
            const varCatalogItem: [*c]u8 = frontier_softmenus.dynmenuGetLabel(dynamicMenuItem);
            if (strcmp(varCatalogItem, "XEQ") != 0) {
                const label: calcRegister_t = frontier_manage.findNamedLabel(varCatalogItem, frontier_manage.GLOBAL_LABELS);
                if (label != INVALID_VARIABLE) {
                    if (calcMode == CM_PEM) {
                        frontier_manage.insertUserItemInProgram(func, varCatalogItem);
                    } else {
                        reallyRunFunction(func, @bitCast(label));
                    }
                } else {
                    frontier_error.displayCalcErrorMessage(@intCast(ERROR_LABEL_NOT_FOUND), ERR_REGISTER_LINE, REGISTER_X);
                }
                return;
            }
        }
        if (tam.mode == 0 and TM_VALUE <= @as(i16, @bitCast(indexOfItems[@intCast(func)].param)) and @as(i16, @bitCast(indexOfItems[@intCast(func)].param)) <= TM_CMP and (calcMode != CM_PEM or aimBuffer[0] == 0 or nimNumberPart != NP_INT_BASE)) {
            // **Start TAM function
            if (itemNotAvail(func) == 0) {
                frontier_tam.tamEnterMode(func);
            } else {
                if (itemERRTIVal(func) == _TO_ITM_TI) {
                    temporaryInformation = TI_NOT_AVAILABLE;
                } else if (itemERRTIVal(func) == _TO_ITM_ERR) {
                    frontier_error.displayCalcErrorMessage(@intCast(notAvail), ERR_REGISTER_LINE, REGISTER_X);
                }
                screenUpdatingMode = @truncate(SCRUPD_AUTO);
            }
            return;
        }

        if (calcMode == CM_PEM) {
            var doNotAddStep: bool = false;
            switch (func) {
                ITM_EXIT1, ITM_CLRMOD, ITM_SNAP, ITM_NOP, ITM_BASEMENU => {
                    doNotAddStep = currentKeyCode == 32;
                },
                ITM_T_UP_ARROW, ITM_T_DOWN_ARROW, ITM_T_LLEFT_ARROW, ITM_T_RRIGHT_ARROW, ITM_T_LEFT_ARROW, ITM_T_RIGHT_ARROW, ITM_ASSIGN, ITM_XSWAP, ITM_XPARSE, CHR_case, CHR_num, ITM_SCR, ITM_USERMODE => {
                    doNotAddStep = getSystemFlag(@intCast(FLAG_ALPHA)) != 0;
                },
                ITM_EDIT => {
                    doNotAddStep = getSystemFlag(@intCast(FLAG_ALPHA)) == 0;
                },
                else => {},
            }

            if (tam.mode == 0 and ((func != ITM_BACKSPACE and (catalog == 0 or catalog == CATALOG_MVAR or fnKeyInCatalog != 0) and !doNotAddStep) or func == ITM_ENTER)) {
                frontier_manage.addStepInProgram(func);
                return;
            }
        }
    }

    if (comptime !dmcp_build) {
        var tmp: [200]u8 = undefined;
        abi.fmtCStr(&tmp, "^^^^ReallyRunFunction func={d}\n", .{@as(c_int, func)});
        jm_show_comment(&tmp);
    }

    reallyRunFunction(func, indexOfItems[@intCast(func)].param);

    if (funcOK == 0) {
        frontier_error.displayCalcErrorMessage(@intCast(ERROR_ITEM_TO_BE_CODED), ERR_REGISTER_LINE, REGISTER_X);
    }
}

