const ext_allocateLocalRegisters = @extern(ItemFn, .{ .name = "allocateLocalRegisters" });
const ext_configCommon = @extern(ItemFn, .{ .name = "configCommon" });
const ext_flagBrowser = @extern(ItemFn, .{ .name = "flagBrowser" });
const ext_fn10Pow = @extern(ItemFn, .{ .name = "fn10Pow" });
const ext_fn1stDeriv = @extern(ItemFn, .{ .name = "fn1stDeriv" });
